#[test]
fn state_matches_c() {
    unsafe {
        let want = include_str!("data/gro_grinishie2.txt");
        let mut lines = want.lines();
        let verbose = std::env::var("ORACLE_VERBOSE").ok();
        let hdr: std::vec::Vec<usize> = lines.next().unwrap().split_whitespace().skip(1).map(|s| s.parse().unwrap()).collect();
        let sizes: std::vec::Vec<usize> = std::vec![core::mem::size_of::<Ground>(), core::mem::size_of::<HSD_GObj>(), core::mem::size_of::<HSD_JObj>(), core::mem::size_of::<StageInfo>(), core::mem::size_of_val(&*addr_of!(t::yakumono_param)), core::mem::size_of_val(&*addr_of!(t::grI2_803E4A60)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks)), core::mem::size_of_val(&*addr_of!(t::grI2_StageData)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[0].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[1].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[2].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[3].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[4].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[5].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[6].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[7].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[8].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[9].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[10].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[11].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[12].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[13].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[14].x10.flags)), core::mem::size_of_val(&*addr_of!(t::grI2_StageCallbacks[15].x10.flags))];
        assert_eq!(hdr, sizes, "struct sizes (C native layout vs the Rust port)");
        install_hooks();
        world_reg();
        world_reg_fns();
        let mut bad = std::vec::Vec::new();
        for (fi, fnn) in FNS.iter().enumerate() {
            let mut agg = FNV0;
            let vb = verbose.as_deref() == Some(fnn.name);
            if verbose.is_some() && !vb {
                continue;
            }
            for k in 0..fnn.n {
                let mut h = FNV0;
                RS = 0x9E37_79B9u32 ^ ((fi as u32).wrapping_mul(7919).wrapping_add(k.wrapping_mul(104729)).wrapping_add(1));
                world_fill(fi);
                let mut a = core::mem::zeroed::<Args>();
                for i in 0..4 { a.i[i] = rnd() % 4; }
                for i in 0..2 { a.f[i] = rf(); }
                for i in 0..2 { a.v3[i].x = rf(); a.v3[i].y = rf(); a.v3[i].z = rf(); }
                for i in 0..2 { a.v2[i].x = rf(); a.v2[i].y = rf(); }
                for i in 0..2 { a.pf[i] = rf(); }
                for i in 0..2 { a.pi[i] = (rnd() % 8) as i32; }
                case_pre(fi, &mut a);
                LG.clear();
                let (rv, _rb) = call_fn(fi, &mut a);
                let ho = fnv(FNV0, LG.as_bytes());
                let hw = world_hash(fi);
                for x in [ho, rv, hw] {
                    h = fnv(h, &x.to_le_bytes());
                }
                h = fnv(h, &canon_f32_bytes(&[a.v3[0].x, a.v3[0].y, a.v3[0].z, a.v3[1].x, a.v3[1].y, a.v3[1].z]));
                h = fnv(h, &canon_f32_bytes(&[a.v2[0].x, a.v2[0].y, a.v2[1].x, a.v2[1].y]));
                h = fnv(h, &canon_f32_bytes(&a.pf));
                h = fnv(h, bytes(&a.pi));
                if vb {
                    println!("{} {:016x} ret={:x} W={:016x} L={:016x}\n  {}", k, h, rv, hw, ho, LG);
                }
                agg = fnv(agg, &h.to_le_bytes());
            }
            if verbose.is_some() {
                continue;
            }
            let line = lines.next().expect("data file shorter than the function table");
            let (cname, chash) = line.split_once(' ').unwrap();
            assert_eq!(cname, fnn.name, "data file and function table out of step");
            if u64::from_str_radix(chash, 16).unwrap() != agg {
                bad.push(fnn.name);
            }
        }
        assert!(bad.is_empty(), "{} of {} functions differ from the C: {:?}", bad.len(), FNS.len(), bad);
    }
}
